  // CSD_RATIONALE_BEGIN
  // This strategy tracks two pieces of state: the full generated output and a
  // parser-scoped currentConstrained prefix for the arithmetic expression region.
  // Outside of << and >> it uses unconstrained decoding. Once << has appeared
  // without a matching >>, it switches to constrained decoding so every token
  // added inside the arithmetic span remains parser-valid. When >> is emitted,
  // the constrained prefix is reset. This is intended to preserve valid << >>
  // arithmetic content for gsm_symbolic while keeping the overall loop simple
  // and verifier-friendly.
  // CSD_RATIONALE_END
  var helpers := new CSDHelpers();
  generated := [];
  var steps: nat := 0;
  var currentConstrained: Prefix := [];

  while steps < maxSteps
    invariant 0 <= steps <= maxSteps
    invariant |generated| == steps
    invariant helpers.cost == steps
    invariant lm.ValidTokensIdsLogits()
    invariant parser.IsValidPrefix(currentConstrained)
    decreases maxSteps - steps
  {
    if |currentConstrained| == 0 {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      if next == eosToken { break; }
      generated := generated + [next];
      if next == "<<" {
        currentConstrained := ["<<"];
      }
      steps := steps + 1;
    } else {
      var next := helpers.ConstrainedStep(lm, parser, prompt, currentConstrained, eosToken);
      if next == eosToken { break; }
      generated := generated + [next];
      if next == ">>" {
        currentConstrained := [];
      } else {
        currentConstrained := currentConstrained + [next];
      }
      steps := steps + 1;
    }
  }
  cost := helpers.cost;
}

